[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #000000;
      --green: #55DA9B;
      --purple: #5620C1;
      --white: #ffffff;
      --gray-50: #f9fafb;
      --gray-100: #f3f4f6;
      --gray-200: #e5e7eb;
      --gray-300: #d1d5db;
      --gray-400: #9ca3af;
      --gray-500: #6b7280;
      --gray-600: #4b5563;
      --gray-700: #374151;
      --gray-800: #1f2937;
      --gray-900: #111827;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Plus Jakarta Sans', sans-serif;
      background: var(--white);
      color: var(--gray-900);
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* ── NAV ── */
    nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      padding: 0 2rem;
    }
    .nav-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      gap: 2rem;
      height: 64px;
    }
    .logo {
      font-size: 1.35rem;
      font-weight: 900;
      color: var(--black);
      text-decoration: none;
      letter-spacing: -0.5px;
      display: flex;
      align-items: center;
      gap: 0.4rem;
    }
    .logo-dot {
      width: 10px;
      height: 10px;
      background: var(--green);
      border-radius: 50%;
      display: inline-block;
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.5rem;
      margin-left: auto;
    }
    .nav-links a {
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--gray-600);
      text-decoration: none;
      transition: color 0.2s;
    }
    .nav-links a:hover { color: var(--black); }
    .btn-nav-signup {
      background: var(--black);
      color: var(--white);
      border: none;
      border-radius: 999px;
      padding: 0.5rem 1.25rem;
      font-size: 0.875rem;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
      transition: background 0.2s, transform 0.15s;
    }
    .btn-nav-signup:hover { background: var(--purple); transform: translateY(-1px); }

    /* ── HERO ── */
    .hero {
      background: var(--black);
      color: var(--white);
      padding: 5rem 2rem 4rem;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(86,32,193,0.35) 0%, transparent 70%),
                  radial-gradient(ellipse 50% 40% at 80% 80%, rgba(85,218,155,0.15) 0%, transparent 60%);
      pointer-events: none;
    }
    .hero-inner {
      position: relative;
      max-width: 760px;
      margin: 0 auto;
    }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      background: rgba(85,218,155,0.15);
      border: 1px solid rgba(85,218,155,0.3);
      color: var(--green);
      border-radius: 999px;
      padding: 0.35rem 0.9rem;
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      margin-bottom: 1.5rem;
    }
    .hero h1 {
      font-size: clamp(2.25rem, 5vw, 3.75rem);
      font-weight: 900;
      line-height: 1.1;
      letter-spacing: -1px;
      margin-bottom: 1rem;
    }
    .hero h1 span { color: var(--green); }
    .hero-subtitle {
      font-size: 1.2rem;
      color: rgba(255,255,255,0.7);
      margin-bottom: 2.5rem;
      font-weight: 500;
    }
    .hero-ctas {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 0.75rem;
      margin-bottom: 1.25rem;
    }
    .btn-google {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.7rem;
      background: var(--white);
      color: var(--gray-800);
      border: none;
      border-radius: 999px;
      padding: 0.85rem 2rem;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
      width: 340px;
      max-width: 100%;
      transition: transform 0.15s, box-shadow 0.15s;
      box-shadow: 0 4px 16px rgba(0,0,0,0.2);
    }
    .btn-google:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(0,0,0,0.3); }
    .btn-email {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.7rem;
      background: transparent;
      color: var(--white);
      border: 2px solid rgba(255,255,255,0.35);
      border-radius: 999px;
      padding: 0.85rem 2rem;
      font-size: 1rem;
      font-weight: 700;
      cursor: pointer;
      font-family: inherit;
      width: 340px;
      max-width: 100%;
      transition: border-color 0.2s, background 0.2s, transform 0.15s;
    }
    .btn-email:hover { border-color: var(--green); background: rgba(85,218,155,0.08); transform: translateY(-2px); }
    .hero-legal {
      font-size: 0.72rem;
      color: rgba(255,255,255,0.35);
      max-width: 500px;
      margin: 0 auto 2.5rem;
      line-height: 1.5;
    }
    .hero-legal a { color: rgba(255,255,255,0.5); text-decoration: underline; }

    /* Category pills */
    .hero-categories {
      display: flex;
      gap: 0.5rem;
      overflow-x: auto;
      padding-bottom: 0.5rem;
      justify-content: center;
      flex-wrap: wrap;
      scrollbar-width: none;
    }
    .hero-categories::-webkit-scrollbar { display: none; }
    .pill {
      flex-shrink: 0;
      background: rgba(255,255,255,0.08);
      border: 1px solid rgba(255,255,255,0.15);
      color: rgba(255,255,255,0.85);
      border-radius: 999px;
      padding: 0.4rem 1rem;
      font-size: 0.82rem;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.2s, border-color 0.2s, color 0.2s;
      white-space: nowrap;
    }
    .pill:hover { background: var(--green); border-color: var(--green); color: var(--black); }

    /* Hero illustration grid */
    .hero-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0.75rem;
      margin-top: 3.5rem;
      max-width: 900px;
      margin-left: auto;
      margin-right: auto;
    }
    .hero-card {
      border-radius: 16px;
      overflow: hidden;
      aspect-ratio: 4/3;
      position: relative;
    }
    .hero-card-bg {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.5rem;
      position: relative;
    }
    .hero-card-label {
      position: absolute;
      bottom: 0;
      left: 0;
      right: 0;
      background: linear-gradient(transparent, rgba(0,0,0,0.75));
      color: white;
      font-size: 0.7rem;
      font-weight: 700;
      padding: 1.5rem 0.6rem 0.6rem;
      text-align: left;
    }

    /* ── SECTION COMMON ── */
    section { padding: 5rem 2rem; }
    .section-inner { max-width: 1280px; margin: 0 auto; }
    .section-tag {
      display: inline-block;
      background: var(--green);
      color: var(--black);
      border-radius: 999px;
      padding: 0.25rem 0.85rem;
      font-size: 0.75rem;
      font-weight: 800;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      margin-bottom: 1rem;
    }
    .section-title {
      font-size: clamp(1.75rem, 3vw, 2.75rem);
      font-weight: 900;
      letter-spacing: -0.5px;
      line-height: 1.15;
      margin-bottom: 0.75rem;
    }
    .section-subtitle {
      font-size: 1.05rem;
      color: var(--gray-500);
      max-width: 600px;
      margin-bottom: 3rem;
    }

    /* ── FEATURES ── */
    .features { background: var(--gray-50); }
    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 1.5rem;
      margin-top: 3rem;
    }
    .feature-card {
      background: var(--white);
      border-radius: 20px;
      padding: 2rem;
      border: 1px solid var(--gray-200);
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .feature-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
    .feature-icon {
      width: 52px;
      height: 52px;
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.5rem;
      margin-bottom: 1.25rem;
    }
    .feature-card h3 { font-size: 1.05rem; font-weight: 800; margin-bottom: 0.5rem; }
    .feature-card p { font-size: 0.9rem; color: var(--gray-500); line-height: 1.6; }

    /* ── STATS ── */
    .stats { background: var(--black); color: var(--white); padding: 4.5rem 2rem; }
    .stats-grid {
      max-width: 1000px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2rem;
      text-align: center;
    }
    .stat-number {
      font-size: clamp(2.5rem, 5vw, 3.5rem);
      font-weight: 900;
      color: var(--green);
      line-height: 1;
      margin-bottom: 0.4rem;
      letter-spacing: -1px;
    }
    .stat-label {
      font-size: 0.9rem;
      color: rgba(255,255,255,0.55);
      font-weight: 600;
      letter-spacing: 0.03em;
    }

    /* ── COURSES ── */
    .course-tabs {
      display: flex;
      gap: 0.4rem;
      overflow-x: auto;
      scrollbar-width: none;
      padding-bottom: 0.25rem;
      margin-bottom: 2.5rem;
      flex-wrap: wrap;
    }
    .course-tabs::-webkit-scrollbar { display: none; }
    .tab-btn {
      flex-shrink: 0;
      background: transparent;
      border: 1.5px solid var(--gray-200);
      border-radius: 999px;
      padding: 0.45rem 1rem;
      font-size: 0.82rem;
      font-weight: 700;
      color: var(--gray-600);
      cursor: pointer;
      font-family: inherit;
      transition: all 0.2s;
      white-space: nowrap;
    }
    .tab-btn:hover { border-color: var(--purple); color: var(--purple); }
    .tab-btn.active { background: var(--black); color: var(--white); border-color: var(--black); }

    .courses-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 1.5rem;
    }
    .course-card {
      border-radius: 18px;
      overflow: hidden;
      border: 1px solid var(--gray-200);
      background: var(--white);
      transition: transform 0.2s, box-shadow 0.2s;
      cursor: pointer;
    }
    .course-card:hover { transform: translateY(-4px); box-shadow: 0 16px 48px rgba(0,0,0,0.1); }
    .course-thumb {
      aspect-ratio: 16/9;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
      position: relative;
      overflow: hidden;
    }
    .course-thumb-label {
      position: absolute;
      top: 0.75rem;
      right: 0.75rem;
      background: rgba(0,0,0,0.6);
      color: white;
      border-radius: 999px;
      padding: 0.2rem 0.6rem;
      font-size: 0.72rem;
      font-weight: 700;
      backdrop-filter: blur(4px);
    }
    .course-body { padding: 1.25rem; }
    .course-body h3 {
      font-size: 0.9rem;
      font-weight: 700;
      line-height: 1.4;
      margin-bottom: 0.6rem;
      color: var(--gray-900);
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .course-meta {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.78rem;
      color: var(--gray-500);
      font-weight: 600;
    }
    .course-meta span { display: flex; align-items: center; gap: 0.25rem; }
    .course-instructor {
      font-size: 0.8rem;
      color: var(--gray-600);
      font-weight: 600;
      margin-bottom: 0.5rem;
    }

    /* ── CREATIVE FEED ── */
    .creative-feed { background: var(--gray-50); }
    .feed-layout {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
    }
    .feed-features { display: flex; flex-direction: column; gap: 2rem; }
    .feed-item {
      display: flex;
      gap: 1.25rem;
      align-items: flex-start;
    }
    .feed-icon {
      flex-shrink: 0;
      width: 48px;
      height: 48px;
      border-radius: 14px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.4rem;
    }
    .feed-item h3 { font-size: 1rem; font-weight: 800; margin-bottom: 0.3rem; }
    .feed-item p { font-size: 0.88rem; color: var(--gray-500); line-height: 1.6; }
    .feed-visual {
      border-radius: 24px;
      overflow: hidden;
      background: linear-gradient(135deg, #5620C1 0%, #55DA9B 100%);
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 5rem;
      position: relative;
    }
    .feed-visual-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0.75rem;
      padding: 1.5rem;
      width: 100%;
      height: 100%;
    }
    .feed-mini-card {
      background: rgba(255,255,255,0.15);
      backdrop-filter: blur(8px);
      border-radius: 12px;
      padding: 0.75rem;
      display: flex;
      flex-direction: column;
      gap: 0.4rem;
      border: 1px solid rgba(255,255,255,0.2);
    }
    .feed-mini-card-avatar {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.9rem;
    }
    .feed-mini-card-text {
      font-size: 0.65rem;
      font-weight: 700;
      color: white;
      line-height: 1.3;
    }
    .feed-mini-card-sub {
      font-size: 0.58rem;
      color: rgba(255,255,255,0.65);
    }

    /* ── TEACHERS ── */
    .teachers-scroll-wrapper {
      position: relative;
      margin: 0 -2rem;
      padding: 0 2rem;
      overflow: hidden;
    }
    .teachers-scroll {
      display: flex;
      gap: 1.25rem;
      overflow-x: auto;
      scrollbar-width: none;
      scroll-behavior: smooth;
      padding-bottom: 1rem;
    }
    .teachers-scroll::-webkit-scrollbar { display: none; }
    .teacher-card {
      flex-shrink: 0;
      width: 220px;
      border-radius: 20px;
      overflow: hidden;
      border: 1px solid var(--gray-200);
      background: var(--white);
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .teacher-card:hover { transform: translateY(-4px); box-shadow: 0 16px 40px rgba(0,0,0,0.1); }
    .teacher-avatar {
      aspect-ratio: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      font-weight: 900;
      color: white;
    }
    .teacher-info { padding: 1rem; }
    .teacher-info h3 { font-size: 0.9rem; font-weight: 800; margin-bottom: 0.2rem; }
    .teacher-info p { font-size: 0.78rem; color: var(--gray-500); font-weight: 600; }
    .teachers-nav {
      display: flex;
      gap: 0.75rem;
      margin-top: 2rem;
    }
    .teachers-nav button {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 2px solid var(--gray-200);
      background: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      font-size: 1.1rem;
      transition: all 0.2s;
    }
    .teachers-nav button:hover { background: var(--black); color: var(--white); border-color: var(--black); }

    /* ── TESTIMONIALS ── */
    .testimonials { background: var(--gray-50); }
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 1.5rem;
    }
    .testimonial-card {
      background: var(--white);
      border-radius: 20px;
      padding: 2rem;
      border: 1px solid var(--gray-200);
      position: relative;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .testimonial-card:hover { transform: translateY(-3px); box-shadow: 0 10px 36px rgba(0,0,0,0.07); }
    .testimonial-stars {
      color: #f59e0b;
      font-size: 0.9rem;
      margin-bottom: 1rem;
      letter-spacing: 2px;
    }
    .testimonial-quote {
      font-size: 0.95rem;
      line-height: 1.7;
      color: var(--gray-700);
      margin-bottom: 1.5rem;
      font-style: italic;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }
    .author-avatar {
      width: 42px;
      height: 42px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.1rem;
      font-weight: 800;
      color: white;
    }
    .author-name { font-size: 0.88rem; font-weight: 800; }

    /* ── TEAMS ── */
    .teams {
      background: linear-gradient(135deg, #5620C1 0%, #3a11a0 100%);
      color: white;
    }
    .teams-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
    }
    .teams h2 {
      font-size: clamp(1.75rem, 3vw, 2.5rem);
      font-weight: 900;
      letter-spacing: -0.5px;
      margin-bottom: 1.25rem;
      line-height: 1.15;
    }
    .teams h2 span { color: var(--green); }
    .teams p { font-size: 1rem; color: rgba(255,255,255,0.75); line-height: 1.7; margin-bottom: 2rem; }
    .btn-teams {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      background: var(--green);
      color: var(--black);
      border: none;
      border-radius: 999px;
      padding: 0.85rem 2rem;
      font-size: 1rem;
      font-weight: 800;
      cursor: pointer;
      font-family: inherit;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .btn-teams:hover { transform: translateY(-2px); box-shadow: 0 8px 24px rgba(85,218,155,0.35); }
    .teams-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
    }
    .teams-viz-card {
      background: rgba(255,255,255,0.1);
      border-radius: 16px;
      padding: 1.25rem;
      border: 1px solid rgba(255,255,255,0.15);
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
    }
    .teams-viz-card:first-child { grid-column: span 2; }
    .teams-viz-card-icon { font-size: 1.5rem; margin-bottom: 0.25rem; }
    .teams-viz-card h4 { font-size: 0.85rem; font-weight: 800; color: white; }
    .teams-viz-card p { font-size: 0.75rem; color: rgba(255,255,255,0.6); line-height: 1.5; }

    /* ── FAQ ── */
    .faq-list { max-width: 760px; margin: 0 auto; }
    .faq-item {
      border-bottom: 1.5px solid var(--gray-200);
      overflow: hidden;
    }
    .faq-item:first-child { border-top: 1.5px solid var(--gray-200); }
    .faq-question {
      width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      padding: 1.5rem 0;
      background: none;
      border: none;
      font-family: inherit;
      font-size: 1rem;
      font-weight: 700;
      color: var(--gray-900);
      cursor: pointer;
      text-align: left;
      transition: color 0.2s;
    }
    .faq-question:hover { color: var(--purple); }
    .faq-icon {
      flex-shrink: 0;
      width: 28px;
      height: 28px;
      border-radius: 50%;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.1rem;
      font-weight: 300;
      transition: transform 0.3s, background 0.2s;
      line-height: 1;
    }
    .faq-item.open .faq-icon { transform: rotate(45deg); background: var(--green); }
    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.35s ease, padding 0.2s;
    }
    .faq-item.open .faq-answer { max-height: 400px; }
    .faq-answer-inner {
      padding: 0 0 1.5rem;
      font-size: 0.95rem;
      color: var(--gray-600);
      line-height: 1.7;
    }

    /* ── FOOTER ── */
    footer {
      background: var(--black);
      color: var(--white);
      padding: 4rem 2rem 2rem;
    }
    .footer-inner { max-width: 1280px; margin: 0 auto; }
    .footer-top {
      display: grid;
      grid-template-columns: 1.5fr repeat(4, 1fr);
      gap: 2.5rem;
